from lib import *
S = SS('t17')
steps = [
    step("分布式锁用来保护“读—改—写”。8 个线程各给同一个计数器加 100 次,应得 800。不加锁(SELECT 再 UPDATE):最终值 101,丢了 699 次更新。加 Redis 锁(SET NX PX,解锁用 Lua 比较令牌):最终值 800,丢 0,用时 0.86 s(928 操作/秒)。不用锁、一条原子 UPDATE v = v + 1:800,丢 0,用时 0.09 s(9274 操作/秒)。锁确实能让读改写变成互斥,但同样的效果,让数据库自己做原子更新要快得多。", t=tl(S(1)), mark=lidx(S(1), '不加锁(SELECT 再 UPDATE)'), done=lidx(S(1), 'Redis 锁 + SELECT 再 UPDATE', '一条原子 UPDATE'), b=bars([['不加锁:丢失的更新', 699, '699 / 800'], ['Redis 锁:丢失的更新', 0, '0'], ['Redis 锁 操作/秒', 928, '928'], ['原子 UPDATE 操作/秒', 9274, '9274']], 9300, mark=[0], done=[1], cur=[2, 3]), kv=KV([['不加锁', '800 次只剩 101'], ['Redis 锁', '800,但慢(928 操作/秒)'], ['原子 UPDATE', '800,9274 操作/秒']], ['Redis 锁'])),
    step("锁过期而持有者还不知道。A 拿到锁(TTL 500 ms)、读到 v=0 之后整个进程被冻住 1 秒(SIGSTOP,模拟 GC 停顿、虚拟机迁移或被换出),B 在锁过期后(498 ms)拿到锁,读到 v=0,写 v=1;1004 ms 时 A 醒来,按它读到的 v=0 写了 v=1。两个客户端各加 1,计数器应该是 2,实际是 1:一次更新悄悄丢了,两边都以为自己是在锁保护下写的。把保护加强一点——A 在写之前先检查“锁还是不是我的”(检查为真),检查通过之后才被冻住:B 在 196 ms 拿到锁并写入,1006 ms A 照样写,结果还是 1。检查和写之间总有空隙,进程可以在那里被冻住。", t=tl(S(2)), mark=lidx(S(2), '[A] WROTE v=1', '[B] LOCKED fence=2'), done=lidx(S(2), '[B] WROTE v=1', 'CHECK_PASSED'), b=bars([['期望的计数器值', 2, '2'], ['实际的计数器值(无防护)', 1, '1'], ['实际的计数器值(写前检查)', 1, '1']], 2, done=[0], mark=[1, 2]), kv=KV([['锁有 TTL', '持有者被冻住,锁到期被别人拿走'], ['醒来之后', '它不知道,继续写'], ['写前检查', '检查与写之间仍有空隙']], ['醒来之后'])),
    step("fencing token:加锁时再 INCR 一个只增不减的令牌(A 拿到 1,B 拿到 2),写入时由存储端比较——UPDATE ... WHERE token < ?。同样的场景:B 在 503 ms 用令牌 2 写入,受影响行数 1;A 醒来后(1006 ms)用令牌 1 写入,受影响行数 0,被存储端拒绝(令牌太旧)。计数器是 1,存储里记录的最大令牌是 2。A 的写入被明确拒绝,它知道自己失败了、可以重来,而不是悄悄覆盖 B 的结果。要让锁真正安全,检查必须放在存储那一边。", t=tl(S(3)), mark=lidx(S(3), '[A] WROTE v=1 fence=1'), done=lidx(S(3), '[B] WROTE v=1 fence=2', '计数器 = 1'), b=bars([['B(令牌 2)写入受影响行数', 1, '1'], ['A(令牌 1)写入受影响行数', 0, '0(被拒绝)']], 1, done=[0], mark=[1]), kv=KV([['令牌', '每次加锁单调递增'], ['存储端检查', 'WHERE token < ?'], ['结果', '旧持有者的写入被明确拒绝']], ['结果'])),
    step("锁不是事务。转账分两次独立提交:A 账户扣 100,B 账户加 100,整个过程由一把锁保护。持锁进程在“已扣款、未入账”时被 kill -9:此刻账户是 (1, 900)、(2, 1000),锁还剩 790 ms 过期。1 秒后别的进程照常拿到了锁,账户仍是 (1, 900)、(2, 1000),两个账户的钱合计 1900,应该是 2000。锁到期只是放行了别人,已经做完的那一步没有谁去回滚。要原子地完成多步写入,需要的是事务(或 Saga、TCC),不是锁。", t=tl(S(4)), mark=lidx(S(4), '已扣款、未入账'), done=lidx(S(4), '1 秒后'), b=bars([['转账前两个账户合计', 2000, '2000'], ['kill -9 并等锁过期后合计', 1900, '1900']], 2000, done=[0], mark=[1]), kv=KV([['持锁者崩溃', '锁到期自动释放'], ['已完成的那一步', '不会回滚'], ['缺少', '原子性:要靠事务或补偿']], ['缺少'])),
    step("同一个热点行,三种保护方式的吞吐(8 个线程各 300 次,3 轮中位数)。Redis 锁 + SELECT 再 UPDATE:3512 操作/秒(范围 3199 到 3551),延迟中位数 0.25 ms、p99 41.81 ms(要自旋等锁)。SELECT ... FOR UPDATE 再 UPDATE(一个事务):6172 操作/秒,p99 3.15 ms。一条原子 UPDATE v = v + 1:9123 操作/秒,p99 1.47 ms。三种最终值都是 2400,没有丢失。数据库自己的行锁 / 原子更新比外面再套一个 Redis 锁便宜,也没有“锁过期”的问题;外部锁主要用在被保护的资源没有这种原子能力的时候。", t=tl(S(5)), mark=lidx(S(5), 'Redis 锁 + SELECT 再 UPDATE'), done=lidx(S(5), '一条原子 UPDATE'), b=bars([['Redis 锁 操作/秒', 3512, '3512'], ['FOR UPDATE 操作/秒', 6172, '6172'], ['原子 UPDATE 操作/秒', 9123, '9123'], ['Redis 锁 p99 ms', 41.81, '41.81']], 9200, cur=[0, 1, 2], mark=[3]), kv=KV([['吞吐', 'Redis 锁 3512 < FOR UPDATE 6172 < 原子 9123'], ['尾延迟', 'Redis 锁 p99 41.81 ms'], ['何时用外部锁', '资源本身没有原子更新能力']], ['何时用外部锁'])),
]
A = mkartt('t17', 17, '分布式事务,分布式锁,Redis,fencing token,MySQL,真实验证,动画演示',
    '实测分布式锁与事务的关系:Redis 锁能把 800 次读改写从丢 699 次变成 0 丢失,但比原子 UPDATE 慢 10 倍;持有者被 SIGSTOP 冻住 1 秒、锁过期后 A 醒来照样写,计数器 2 变 1(写前检查也没用);fencing token 让旧持有者的写入被存储端拒绝;持锁者 kill -9 后转账少了 100,锁不是事务。',
    '分布式锁和分布式事务常被混在一起说。锁能防住并发的读改写,可它的 TTL 会过期、持有者会被冻住,过期之后会怎样?锁能不能保证多步写入要么都做要么都不做?这篇用真实的 Redis、MySQL 和 SIGSTOP / kill -9,把这几个问题一个个量出来。',
    [('699 → 0', '800 次读改写更新:不加锁丢的次数 → 加 Redis 锁丢的次数'), ('2 → 1', '持有者被冻住 1 秒、锁过期后,两个客户端各加 1 的计数器最终值(写前检查也一样)'), ('100', '持锁转账进程 kill -9 后,两个账户合计少掉的钱(1900,应为 2000)')],
    [('锁保护读改写', '<p>不加锁丢 699 次更新,加 Redis 锁一次不丢,但比数据库原子 UPDATE 慢约 10 倍。</p>'),
     ('锁会过期', '<p>持有者被冻住、锁到期后,别的客户端拿到锁并写入;持有者醒来不知道锁已失效,照样写,更新被悄悄覆盖。写前检查锁也堵不住,检查与写之间有空隙。</p>'),
     ('fencing token', '<p>加锁时拿一个单调递增的令牌,存储端在写入时比较,旧令牌的写入被明确拒绝。</p>'),
     ('锁不是事务', '<p>持锁者崩溃后锁到期放行别人,已完成的那一步不会回滚;多步写入的原子性靠事务或补偿。</p>'),
     ('吞吐对比', '<p>数据库行锁 / 原子更新比再套一层 Redis 锁快,也没有锁过期的问题。</p>')],
    steps,
    [ENV_T + '。本篇用 MySQL 26.7.0(ctr、acct 两张表)和自己起的 Redis 8.10.2;锁是 SET key token NX PX ttl,解锁用 Lua 比较令牌再删;“GC 停顿”用对客户端子进程发 SIGSTOP / SIGCONT 模拟;吞吐是 8 个线程、3 轮取中位数,Redis 锁是自旋加锁(间隔 2 ms)',
     '没有验证:Redlock 等多节点 Redis 锁方案;etcd / ZooKeeper 的租约锁(它们同样有过期问题);Redis 主从切换时锁丢失;Redis 锁用在真实网络(跨机)下的延迟;真实 GC 停顿的时长分布(这里是 1 秒的人为停顿)'],
    '分布式锁')
